mapper.select:
SELECT SETTLEMENT_ID as settlementId, ORG_CODE as orgCode, ORG_NAME as orgName, PERIOD_SCHEME as periodScheme, ACCOUNTING_PERIOD as accountingPeriod, SETTLEMENT_STATUS as settlementStatus, CASE SETTLEMENT_STATUS WHEN 0 THEN '未结账' WHEN 1 THEN '已结账' ELSE '未知' END as settlementStatusName, SETTLEMENT_USER_ID as settlementUserId, SETTLEMENT_USER_NAME as settlementUserName, SETTLEMENT_TIME as settlementTime, CANCEL_USER_ID as cancelUserId, CANCEL_USER_NAME as cancelUserName, CANCEL_TIME as cancelTime, BOOK_ID as bookId, TENANT_ID as tenantId, CREATE_TIME as createTime, UPDATE_TIME as updateTime FROM T_REVENUE_BATCH_SETTLEMENT
IS_DELETED = 0
AND ORG_CODE LIKE '%' || #{param.orgCode} || '%'
AND ORG_NAME LIKE '%' || #{param.orgName} || '%'
AND PERIOD_SCHEME = #{param.periodScheme}
AND ACCOUNTING_PERIOD = #{param.accountingPeriod}
AND SETTLEMENT_STATUS = #{param.settlementStatus}
AND BOOK_ID = #{param.bookId}
AND TENANT_ID = #{param.tenantId}
ORDER BY CREATE_TIME DESC

SELECT SETTLEMENT_ID as SETTLEMENTID, ORG_CODE as ORGCODE, ORG_NAME as ORGNAME, PERIOD_SCHEME as PERIODSCHEME, ACCOUNTING_PERIOD as ACCOUNTINGPERIOD, SETTLEMENT_STATUS as SETTLEMENTSTATUS, CASE SETTLEMENT_STATUS WHEN 0 THEN '未结账' WHEN 1 THEN '已结账' ELSE '未知' END as SETTLEMENTSTATUSNAME, SETTLEMENT_USER_ID as SETTLEMENTUSERID, SETTLEMENT_USER_NAME as SETTLEMENTUSERNAME, SETTLEMENT_TIME as SETTLEMENTTIME, CANCEL_USER_ID as CANCELUSERID, CANCEL_USER_NAME as CANCELUSERNAME, CANCEL_TIME as CANCELTIME, CREATE_TIME as CREATETIME FROM T_REVENUE_BATCH_SETTLEMENT
IS_DELETED = 0
AND ORG_CODE LIKE '%' || #{param.orgCode} || '%'
AND ORG_NAME LIKE '%' || #{param.orgName} || '%'
AND PERIOD_SCHEME = #{param.periodScheme}
AND ACCOUNTING_PERIOD = #{param.accountingPeriod}
AND SETTLEMENT_STATUS = #{param.settlementStatus}
ORDER BY CREATE_TIME DESC
